export class Carrera {
  codigo;
  anioVigencia;
  nombre;
  plan;
  constructor(codigo, anioVigencia, nombre, plan) {
    this.codigo = codigo;
    this.anioVigencia = anioVigencia;
    this.nombre = nombre;
    this.plan = plan;
  }
  getCodigo() {
    return this.codigo;
  }
  getAnioVigencia() {
    return this.anioVigencia;
  }
  getNombre() {
    return this.nombre;
  }
  getPlanEstudio() {
    return this.plan;
  }
  getTotalMaterias() {
    return this.plan.getMaterias().length;
  }
}
